INSERT INTO exercises (id, user_id, name, instructions, primary_muscle, secondary_muscles, equipment, joint_tags, compound) VALUES
(md5('exercise:Barbell Bench Press')::uuid, NULL, 'Barbell Bench Press', 'Lie with your eyes under the bar. Pull your shoulder blades back and down and grip slightly wider than shoulder width. Lower the bar to mid chest with elbows about 45 degrees from your torso, then press up and slightly back. Keep feet planted and hips on the bench.', 'CHEST', ARRAY['TRICEPS', 'SHOULDERS'], 'BARBELL', ARRAY['SHOULDER', 'ELBOW', 'WRIST'], TRUE),
(md5('exercise:Incline Barbell Bench Press')::uuid, NULL, 'Incline Barbell Bench Press', 'Set the bench to about 30 degrees. Unrack with shoulder blades pinched, lower the bar to the upper chest under control and press back up over your shoulders. Do not flare the elbows past 60 degrees.', 'CHEST', ARRAY['SHOULDERS', 'TRICEPS'], 'BARBELL', ARRAY['SHOULDER', 'ELBOW', 'WRIST'], TRUE),
(md5('exercise:Dumbbell Bench Press')::uuid, NULL, 'Dumbbell Bench Press', 'Sit with dumbbells on your thighs, lie back and kick them up. Lower until elbows are just below the bench with forearms vertical, then press up and slightly together without clanking the weights.', 'CHEST', ARRAY['TRICEPS', 'SHOULDERS'], 'DUMBBELL', ARRAY['SHOULDER', 'ELBOW'], TRUE),
(md5('exercise:Incline Dumbbell Press')::uuid, NULL, 'Incline Dumbbell Press', 'Bench at 30 degrees. Press the dumbbells from shoulder level to full extension over the upper chest, then lower slowly for a full stretch. Keep your back against the pad.', 'CHEST', ARRAY['SHOULDERS', 'TRICEPS'], 'DUMBBELL', ARRAY['SHOULDER', 'ELBOW'], TRUE),
(md5('exercise:Dumbbell Fly')::uuid, NULL, 'Dumbbell Fly', 'Lie on a flat bench with a slight bend in the elbows. Open your arms in a wide arc until you feel a chest stretch, then squeeze the dumbbells back together as if hugging a tree. Do not go heavy on this one.', 'CHEST', ARRAY['SHOULDERS'], 'DUMBBELL', ARRAY['SHOULDER', 'ELBOW'], FALSE),
(md5('exercise:Cable Crossover')::uuid, NULL, 'Cable Crossover', 'Set the pulleys high, step forward with a slight lean. With a soft bend in the elbows, sweep the handles down and together in front of your hips, squeeze, then return slowly until you feel the chest stretch.', 'CHEST', ARRAY['SHOULDERS'], 'CABLE', ARRAY['SHOULDER'], FALSE),
(md5('exercise:Machine Chest Press')::uuid, NULL, 'Machine Chest Press', 'Adjust the seat so the handles line up with mid chest. Keep your back flat on the pad and shoulder blades back. Press until the arms are almost straight, then return slowly.', 'CHEST', ARRAY['TRICEPS', 'SHOULDERS'], 'MACHINE', ARRAY['SHOULDER'], TRUE),
(md5('exercise:Push-Up')::uuid, NULL, 'Push-Up', 'Hands slightly wider than shoulders, body in a straight line from head to heels. Lower your chest to a fist above the floor with elbows at about 45 degrees, then press away. Do not let the hips sag.', 'CHEST', ARRAY['TRICEPS', 'SHOULDERS', 'CORE'], 'BODYWEIGHT', ARRAY['WRIST', 'SHOULDER'], TRUE),
(md5('exercise:Incline Push-Up')::uuid, NULL, 'Incline Push-Up', 'Hands on a bench or sturdy surface, body straight. Lower your chest to the edge and press back up. The higher the surface, the easier it is, so progress to the floor over time.', 'CHEST', ARRAY['TRICEPS', 'SHOULDERS'], 'BODYWEIGHT', ARRAY['WRIST'], TRUE),
(md5('exercise:Chest Dip')::uuid, NULL, 'Chest Dip', 'On parallel bars lean your torso forward about 30 degrees. Lower until upper arms are about parallel to the floor, then press up. Stop short of any pinching in the front of the shoulder.', 'CHEST', ARRAY['TRICEPS', 'SHOULDERS'], 'BODYWEIGHT', ARRAY['SHOULDER', 'ELBOW'], TRUE),
(md5('exercise:Pec Deck')::uuid, NULL, 'Pec Deck', 'Seat height so the handles sit at chest level. With a slight elbow bend, bring the handles together in front of you and pause, then return slowly to a comfortable stretch.', 'CHEST', ARRAY['SHOULDERS'], 'MACHINE', ARRAY['SHOULDER'], FALSE),
(md5('exercise:Conventional Deadlift')::uuid, NULL, 'Conventional Deadlift', 'Bar over mid foot, hip width stance. Hinge down and grip just outside your legs, chest up, back flat. Push the floor away while keeping the bar against your legs, lock out by squeezing glutes, then lower with the same path. Never round your lower back.', 'BACK', ARRAY['HAMSTRINGS', 'GLUTES', 'FOREARMS'], 'BARBELL', ARRAY['LOWER_BACK'], TRUE),
(md5('exercise:Barbell Row')::uuid, NULL, 'Barbell Row', 'Hinge to about 45 degrees with a flat back. Pull the bar to your lower ribs, driving elbows back, pause, then lower under control. Keep your torso still and do not jerk the weight.', 'BACK', ARRAY['BICEPS', 'SHOULDERS'], 'BARBELL', ARRAY['LOWER_BACK'], TRUE),
(md5('exercise:One-Arm Dumbbell Row')::uuid, NULL, 'One-Arm Dumbbell Row', 'Support one hand and knee on a bench. Pull the dumbbell toward your hip, elbow close to the body, squeeze the shoulder blade, then lower fully for a stretch.', 'BACK', ARRAY['BICEPS'], 'DUMBBELL', ARRAY[]::text[], TRUE),
(md5('exercise:Lat Pulldown')::uuid, NULL, 'Lat Pulldown', 'Grip slightly wider than shoulders, thighs secured under the pad. Lean back slightly, pull the bar to your upper chest by driving elbows down, then let it rise until your arms are straight.', 'BACK', ARRAY['BICEPS'], 'CABLE', ARRAY['ELBOW'], TRUE),
(md5('exercise:Pull-Up')::uuid, NULL, 'Pull-Up', 'Hang with an overhand grip a little wider than shoulders. Pull until your chin clears the bar, leading with your chest, then lower to a full hang. Use a band or assisted machine until you can do clean reps.', 'BACK', ARRAY['BICEPS', 'FOREARMS'], 'BODYWEIGHT', ARRAY['SHOULDER', 'ELBOW'], TRUE),
(md5('exercise:Chin-Up')::uuid, NULL, 'Chin-Up', 'Underhand shoulder width grip. Pull your chin over the bar, keeping your core tight and not swinging, then lower under control to straight arms.', 'BACK', ARRAY['BICEPS'], 'BODYWEIGHT', ARRAY['ELBOW', 'SHOULDER'], TRUE),
(md5('exercise:Seated Cable Row')::uuid, NULL, 'Seated Cable Row', 'Sit tall with a slight knee bend. Pull the handle to your stomach, squeezing the shoulder blades together, then extend your arms without letting your torso rock.', 'BACK', ARRAY['BICEPS'], 'CABLE', ARRAY['LOWER_BACK'], TRUE),
(md5('exercise:T-Bar Row')::uuid, NULL, 'T-Bar Row', 'Straddle the bar, hinge with a flat back and pull the handle to your chest. Pause, then lower until the arms are straight. Keep your head in line with your spine.', 'BACK', ARRAY['BICEPS', 'SHOULDERS'], 'BARBELL', ARRAY['LOWER_BACK'], TRUE),
(md5('exercise:Chest-Supported Machine Row')::uuid, NULL, 'Chest-Supported Machine Row', 'Chest against the pad, handles in both hands. Pull your elbows back past your torso, squeeze, then return slowly. The pad removes the lower back from the movement.', 'BACK', ARRAY['BICEPS', 'SHOULDERS'], 'MACHINE', ARRAY[]::text[], TRUE),
(md5('exercise:Straight-Arm Pulldown')::uuid, NULL, 'Straight-Arm Pulldown', 'Stand facing a high pulley, arms nearly straight. Sweep the bar down to your thighs using your lats, pause, then return slowly overhead without bending the elbows much.', 'BACK', ARRAY[]::text[], 'CABLE', ARRAY['SHOULDER'], FALSE),
(md5('exercise:Inverted Row')::uuid, NULL, 'Inverted Row', 'Lie under a low bar or sturdy table edge, body straight. Pull your chest to the bar and lower slowly. Bend your knees to make it easier.', 'BACK', ARRAY['BICEPS'], 'BODYWEIGHT', ARRAY['ELBOW'], TRUE),
(md5('exercise:Back Extension')::uuid, NULL, 'Back Extension', 'On a hyperextension bench, hinge at the hips until your torso is about level with your legs, then raise to a straight line. Do not hyperextend past neutral at the top.', 'BACK', ARRAY['GLUTES', 'HAMSTRINGS'], 'BODYWEIGHT', ARRAY['LOWER_BACK'], FALSE),
(md5('exercise:Dumbbell Shrug')::uuid, NULL, 'Dumbbell Shrug', 'Stand holding dumbbells at your sides. Lift your shoulders straight up toward your ears, hold for a second, then lower. Do not roll the shoulders.', 'BACK', ARRAY['FOREARMS'], 'DUMBBELL', ARRAY[]::text[], FALSE),
(md5('exercise:Overhead Press')::uuid, NULL, 'Overhead Press', 'Bar at collarbone, grip just outside shoulders. Squeeze glutes, press the bar straight up as your head moves slightly back and then through, finishing with the bar over mid foot. Lower to the collarbone.', 'SHOULDERS', ARRAY['TRICEPS', 'CORE'], 'BARBELL', ARRAY['SHOULDER', 'WRIST', 'LOWER_BACK'], TRUE),
(md5('exercise:Dumbbell Shoulder Press')::uuid, NULL, 'Dumbbell Shoulder Press', 'Seated with back support or standing. Press from shoulder height to full extension over your head, then lower until your elbows are just below shoulder level.', 'SHOULDERS', ARRAY['TRICEPS'], 'DUMBBELL', ARRAY['SHOULDER'], TRUE),
(md5('exercise:Arnold Press')::uuid, NULL, 'Arnold Press', 'Start with palms facing you at chest height. Press up while rotating your palms to face forward, finishing like a normal press. Reverse the rotation on the way down.', 'SHOULDERS', ARRAY['TRICEPS'], 'DUMBBELL', ARRAY['SHOULDER'], TRUE),
(md5('exercise:Dumbbell Lateral Raise')::uuid, NULL, 'Dumbbell Lateral Raise', 'Slight bend in the elbows, raise the dumbbells out to the sides until your arms are about parallel to the floor, leading with the elbows. Lower slowly. Light weight and strict form win here.', 'SHOULDERS', ARRAY[]::text[], 'DUMBBELL', ARRAY['SHOULDER'], FALSE),
(md5('exercise:Cable Lateral Raise')::uuid, NULL, 'Cable Lateral Raise', 'Stand side-on to a low pulley and raise the handle out to the side to shoulder height. The cable keeps tension at the bottom where dumbbells do not.', 'SHOULDERS', ARRAY[]::text[], 'CABLE', ARRAY['SHOULDER'], FALSE),
(md5('exercise:Rear Delt Fly')::uuid, NULL, 'Rear Delt Fly', 'Hinge forward with a flat back, arms hanging. Raise the dumbbells out to the sides with a soft elbow bend, squeezing the rear shoulders, then lower slowly.', 'SHOULDERS', ARRAY['BACK'], 'DUMBBELL', ARRAY['SHOULDER'], FALSE),
(md5('exercise:Reverse Pec Deck')::uuid, NULL, 'Reverse Pec Deck', 'Face the pad. Sweep the handles back in a wide arc until your arms are in line with your shoulders, then return slowly. Keep your chest on the pad.', 'SHOULDERS', ARRAY['BACK'], 'MACHINE', ARRAY['SHOULDER'], FALSE),
(md5('exercise:Machine Shoulder Press')::uuid, NULL, 'Machine Shoulder Press', 'Adjust the seat so the handles start at shoulder height. Press up without shrugging, stop just short of lockout, and lower slowly.', 'SHOULDERS', ARRAY['TRICEPS'], 'MACHINE', ARRAY['SHOULDER'], TRUE),
(md5('exercise:Pike Push-Up')::uuid, NULL, 'Pike Push-Up', 'From a downward dog position with hips high, bend the elbows to lower your head toward the floor between your hands, then press back up. Raise your feet on a bench to make it harder.', 'SHOULDERS', ARRAY['TRICEPS', 'CHEST'], 'BODYWEIGHT', ARRAY['SHOULDER', 'WRIST'], TRUE),
(md5('exercise:Dumbbell Front Raise')::uuid, NULL, 'Dumbbell Front Raise', 'Raise the dumbbells in front of you to shoulder height with straight arms, pause, and lower with control. Do not swing your torso.', 'SHOULDERS', ARRAY[]::text[], 'DUMBBELL', ARRAY['SHOULDER'], FALSE),
(md5('exercise:Face Pull')::uuid, NULL, 'Face Pull', 'Set a rope at face height. Pull it toward your forehead, splitting the rope and pulling your hands past your ears with elbows high. Great for shoulder health.', 'SHOULDERS', ARRAY['BACK'], 'CABLE', ARRAY['SHOULDER'], FALSE),
(md5('exercise:Barbell Curl')::uuid, NULL, 'Barbell Curl', 'Stand tall, elbows at your sides. Curl the bar up without swinging, squeeze at the top, then lower fully. Use an EZ bar if straight bars bother your wrists.', 'BICEPS', ARRAY['FOREARMS'], 'BARBELL', ARRAY['ELBOW', 'WRIST'], FALSE),
(md5('exercise:Dumbbell Curl')::uuid, NULL, 'Dumbbell Curl', 'Curl the dumbbells up, rotating the palms to face you as you lift. Keep your elbows pinned at your sides and lower slowly.', 'BICEPS', ARRAY['FOREARMS'], 'DUMBBELL', ARRAY['ELBOW'], FALSE),
(md5('exercise:Hammer Curl')::uuid, NULL, 'Hammer Curl', 'Palms face each other the whole time. Curl up to shoulder height and lower with control. Works the brachialis and forearms.', 'BICEPS', ARRAY['FOREARMS'], 'DUMBBELL', ARRAY['ELBOW'], FALSE),
(md5('exercise:Incline Dumbbell Curl')::uuid, NULL, 'Incline Dumbbell Curl', 'Sit back on an incline bench with arms hanging behind your torso. Curl up without moving your upper arms, getting a deep stretch at the bottom.', 'BICEPS', ARRAY[]::text[], 'DUMBBELL', ARRAY['ELBOW', 'SHOULDER'], FALSE),
(md5('exercise:Preacher Curl')::uuid, NULL, 'Preacher Curl', 'Upper arms flat on the pad. Curl up and squeeze, then lower slowly but stop just short of locking out to protect the elbow.', 'BICEPS', ARRAY[]::text[], 'MACHINE', ARRAY['ELBOW'], FALSE),
(md5('exercise:Cable Curl')::uuid, NULL, 'Cable Curl', 'Face a low pulley with a straight or EZ attachment. Curl up keeping your elbows by your sides. The cable gives constant tension through the whole range.', 'BICEPS', ARRAY['FOREARMS'], 'CABLE', ARRAY['ELBOW'], FALSE),
(md5('exercise:Close-Grip Bench Press')::uuid, NULL, 'Close-Grip Bench Press', 'Bench press with hands about shoulder width apart and elbows tucked closer to your body. Lower to the lower chest and press up. Do not go narrower than shoulder width.', 'TRICEPS', ARRAY['CHEST', 'SHOULDERS'], 'BARBELL', ARRAY['ELBOW', 'WRIST', 'SHOULDER'], TRUE),
(md5('exercise:Triceps Pushdown')::uuid, NULL, 'Triceps Pushdown', 'Elbows pinned at your sides, push the bar or rope down until your arms are straight, squeeze, then let it rise until your forearms are just past parallel.', 'TRICEPS', ARRAY[]::text[], 'CABLE', ARRAY['ELBOW'], FALSE),
(md5('exercise:Overhead Dumbbell Triceps Extension')::uuid, NULL, 'Overhead Dumbbell Triceps Extension', 'Hold one dumbbell with both hands overhead. Bend the elbows to lower it behind your head, keeping upper arms close to your ears, then extend to the top.', 'TRICEPS', ARRAY[]::text[], 'DUMBBELL', ARRAY['ELBOW', 'SHOULDER'], FALSE),
(md5('exercise:Skull Crusher')::uuid, NULL, 'Skull Crusher', 'Lying on a bench, lower an EZ bar toward your forehead by bending only at the elbows, then extend back up. Keep upper arms vertical.', 'TRICEPS', ARRAY[]::text[], 'BARBELL', ARRAY['ELBOW', 'WRIST'], FALSE),
(md5('exercise:Bench Dip')::uuid, NULL, 'Bench Dip', 'Hands on a bench behind you, legs out front. Lower your body until your elbows are at about 90 degrees, then press up. Keep your back close to the bench.', 'TRICEPS', ARRAY['CHEST', 'SHOULDERS'], 'BODYWEIGHT', ARRAY['SHOULDER', 'ELBOW', 'WRIST'], TRUE),
(md5('exercise:Diamond Push-Up')::uuid, NULL, 'Diamond Push-Up', 'Hands together under your chest forming a diamond. Lower with elbows tracking back and press up. Drop to your knees if needed.', 'TRICEPS', ARRAY['CHEST', 'SHOULDERS'], 'BODYWEIGHT', ARRAY['WRIST', 'ELBOW', 'SHOULDER'], TRUE),
(md5('exercise:Cable Overhead Triceps Extension')::uuid, NULL, 'Cable Overhead Triceps Extension', 'Face away from a pulley with a rope overhead. Extend your arms forward and up until straight, then return slowly for a deep stretch.', 'TRICEPS', ARRAY[]::text[], 'CABLE', ARRAY['ELBOW'], FALSE),
(md5('exercise:Dumbbell Wrist Curl')::uuid, NULL, 'Dumbbell Wrist Curl', 'Forearms on your thighs, palms up. Let the dumbbell roll to your fingertips, then curl it up using only your wrists. Light weight, high reps.', 'FOREARMS', ARRAY[]::text[], 'DUMBBELL', ARRAY['WRIST'], FALSE),
(md5('exercise:Reverse Curl')::uuid, NULL, 'Reverse Curl', 'Overhand grip on an EZ bar. Curl up with elbows at your sides, keeping wrists straight, and lower slowly.', 'FOREARMS', ARRAY['BICEPS'], 'BARBELL', ARRAY['ELBOW', 'WRIST'], FALSE),
(md5('exercise:Farmer''s Carry')::uuid, NULL, 'Farmer''s Carry', 'Hold heavy dumbbells at your sides, stand tall with shoulders back and walk with short quick steps. Reps are steps or seconds. Do not lean or let the weights swing.', 'FOREARMS', ARRAY['CORE', 'BACK'], 'DUMBBELL', ARRAY[]::text[], TRUE),
(md5('exercise:Barbell Back Squat')::uuid, NULL, 'Barbell Back Squat', 'Bar on your upper back, feet shoulder width, toes slightly out. Brace, sit down and back until thighs are at least parallel, knees tracking over toes, then drive up. Keep your chest up and back flat.', 'QUADS', ARRAY['GLUTES', 'HAMSTRINGS', 'CORE'], 'BARBELL', ARRAY['KNEE', 'LOWER_BACK'], TRUE),
(md5('exercise:Front Squat')::uuid, NULL, 'Front Squat', 'Bar rests on your front shoulders with elbows high. Squat straight down keeping an upright torso, then stand. Needs good wrist and shoulder mobility; use straps if the grip hurts.', 'QUADS', ARRAY['GLUTES', 'CORE'], 'BARBELL', ARRAY['KNEE', 'WRIST', 'LOWER_BACK'], TRUE),
(md5('exercise:Goblet Squat')::uuid, NULL, 'Goblet Squat', 'Hold a dumbbell vertically at your chest. Squat down between your knees with an upright torso, elbows inside the knees, then stand. A great way to learn the squat pattern.', 'QUADS', ARRAY['GLUTES', 'CORE'], 'DUMBBELL', ARRAY['KNEE'], TRUE),
(md5('exercise:Leg Press')::uuid, NULL, 'Leg Press', 'Feet shoulder width on the platform. Lower until your knees reach about 90 degrees without your hips curling off the pad, then press without locking the knees hard.', 'QUADS', ARRAY['GLUTES', 'HAMSTRINGS'], 'MACHINE', ARRAY['KNEE', 'LOWER_BACK'], TRUE),
(md5('exercise:Leg Extension')::uuid, NULL, 'Leg Extension', 'Pad on your lower shins. Extend your knees until your legs are straight, squeeze the quads, then lower slowly. Avoid heavy swinging.', 'QUADS', ARRAY[]::text[], 'MACHINE', ARRAY['KNEE'], FALSE),
(md5('exercise:Bulgarian Split Squat')::uuid, NULL, 'Bulgarian Split Squat', 'Rear foot on a bench, front foot far enough forward that your shin stays near vertical. Lower until the back knee is just above the floor, then drive up through the front heel.', 'QUADS', ARRAY['GLUTES'], 'DUMBBELL', ARRAY['KNEE'], TRUE),
(md5('exercise:Walking Lunge')::uuid, NULL, 'Walking Lunge', 'Step forward into a lunge until both knees are at about 90 degrees, then push off the front foot into the next step. Keep your torso upright.', 'QUADS', ARRAY['GLUTES', 'HAMSTRINGS'], 'DUMBBELL', ARRAY['KNEE'], TRUE),
(md5('exercise:Hack Squat')::uuid, NULL, 'Hack Squat', 'Shoulders under the pads, feet forward on the platform. Lower with control until the thighs are parallel or below, then push back up.', 'QUADS', ARRAY['GLUTES'], 'MACHINE', ARRAY['KNEE'], TRUE),
(md5('exercise:Bodyweight Squat')::uuid, NULL, 'Bodyweight Squat', 'Feet shoulder width, arms forward for balance. Sit back and down until your thighs are parallel, then stand. Keep your heels on the floor.', 'QUADS', ARRAY['GLUTES'], 'BODYWEIGHT', ARRAY['KNEE'], TRUE),
(md5('exercise:Dumbbell Step-Up')::uuid, NULL, 'Dumbbell Step-Up', 'Place one foot fully on a box or bench and drive through that heel to stand, then lower slowly. Do all reps on one leg before switching.', 'QUADS', ARRAY['GLUTES'], 'DUMBBELL', ARRAY['KNEE'], TRUE),
(md5('exercise:Reverse Lunge')::uuid, NULL, 'Reverse Lunge', 'Step back and lower until both knees are about 90 degrees, then push through the front foot to return. Easier on the knees than a forward lunge.', 'QUADS', ARRAY['GLUTES', 'HAMSTRINGS'], 'DUMBBELL', ARRAY['KNEE'], TRUE),
(md5('exercise:Romanian Deadlift')::uuid, NULL, 'Romanian Deadlift', 'Hold the bar at hip level, soft knees. Push your hips back, sliding the bar down your thighs until you feel a deep hamstring stretch, then drive the hips forward. Keep your back flat.', 'HAMSTRINGS', ARRAY['GLUTES', 'BACK'], 'BARBELL', ARRAY['LOWER_BACK'], TRUE),
(md5('exercise:Dumbbell Romanian Deadlift')::uuid, NULL, 'Dumbbell Romanian Deadlift', 'Dumbbells in front of your thighs. Hinge at the hips, lowering them down your legs with a flat back, then stand tall by squeezing your glutes.', 'HAMSTRINGS', ARRAY['GLUTES', 'BACK'], 'DUMBBELL', ARRAY['LOWER_BACK'], TRUE),
(md5('exercise:Lying Leg Curl')::uuid, NULL, 'Lying Leg Curl', 'Lie face down with the pad just above your heels. Curl your heels toward your glutes, pause, and lower slowly. Keep your hips pressed into the bench.', 'HAMSTRINGS', ARRAY['CALVES'], 'MACHINE', ARRAY['KNEE'], FALSE),
(md5('exercise:Seated Leg Curl')::uuid, NULL, 'Seated Leg Curl', 'Pad above your ankles, thigh pad snug. Curl your legs back under the seat, squeeze, and return slowly through a full stretch.', 'HAMSTRINGS', ARRAY[]::text[], 'MACHINE', ARRAY['KNEE'], FALSE),
(md5('exercise:Good Morning')::uuid, NULL, 'Good Morning', 'Bar on your upper back, soft knees. Push your hips back until your torso is near parallel with the floor, back flat, then return. Use light weight and strict form.', 'HAMSTRINGS', ARRAY['GLUTES', 'BACK'], 'BARBELL', ARRAY['LOWER_BACK'], TRUE),
(md5('exercise:Nordic Hamstring Curl')::uuid, NULL, 'Nordic Hamstring Curl', 'Kneel with your ankles anchored. Lower your torso toward the floor as slowly as you can, catching yourself with your hands, then push back up. Very demanding, so use as many assists as needed.', 'HAMSTRINGS', ARRAY['CALVES'], 'BODYWEIGHT', ARRAY['KNEE'], FALSE),
(md5('exercise:Single-Leg Romanian Deadlift')::uuid, NULL, 'Single-Leg Romanian Deadlift', 'Balance on one leg with a dumbbell in the opposite hand. Hinge forward while the free leg extends behind you, then return. Keep your hips square to the floor.', 'HAMSTRINGS', ARRAY['GLUTES', 'CORE'], 'DUMBBELL', ARRAY[]::text[], TRUE),
(md5('exercise:Barbell Hip Thrust')::uuid, NULL, 'Barbell Hip Thrust', 'Upper back on a bench, bar over your hips with a pad. Drive through your heels until your hips are fully extended, squeeze the glutes at the top with ribs down, then lower.', 'GLUTES', ARRAY['HAMSTRINGS'], 'BARBELL', ARRAY[]::text[], TRUE),
(md5('exercise:Glute Bridge')::uuid, NULL, 'Glute Bridge', 'Lie on your back, knees bent. Drive your hips up by squeezing your glutes until your body forms a straight line, pause, and lower.', 'GLUTES', ARRAY['HAMSTRINGS'], 'BODYWEIGHT', ARRAY[]::text[], FALSE),
(md5('exercise:Cable Pull-Through')::uuid, NULL, 'Cable Pull-Through', 'Face away from a low pulley with a rope between your legs. Hinge back, then snap your hips forward to stand tall. It is a hip hinge, not a squat.', 'GLUTES', ARRAY['HAMSTRINGS'], 'CABLE', ARRAY['LOWER_BACK'], TRUE),
(md5('exercise:Cable Glute Kickback')::uuid, NULL, 'Cable Glute Kickback', 'Ankle strap on a low pulley. Kick the leg straight back by squeezing the glute, without arching your lower back, then return slowly.', 'GLUTES', ARRAY[]::text[], 'CABLE', ARRAY[]::text[], FALSE),
(md5('exercise:Sumo Deadlift')::uuid, NULL, 'Sumo Deadlift', 'Wide stance, toes out, hands inside your knees. Push the floor apart, keep the chest up and lock out with your hips under the bar.', 'GLUTES', ARRAY['QUADS', 'HAMSTRINGS', 'BACK'], 'BARBELL', ARRAY['LOWER_BACK', 'KNEE'], TRUE),
(md5('exercise:Dumbbell Hip Thrust')::uuid, NULL, 'Dumbbell Hip Thrust', 'Same as the barbell hip thrust with a dumbbell on your hips. A good starting point before loading the bar.', 'GLUTES', ARRAY['HAMSTRINGS'], 'DUMBBELL', ARRAY[]::text[], TRUE),
(md5('exercise:Standing Calf Raise')::uuid, NULL, 'Standing Calf Raise', 'Balls of your feet on the platform. Lower your heels for a full stretch, then rise as high as you can and pause for a second at the top.', 'CALVES', ARRAY[]::text[], 'MACHINE', ARRAY[]::text[], FALSE),
(md5('exercise:Seated Calf Raise')::uuid, NULL, 'Seated Calf Raise', 'With the pad on your thighs, lower the heels deep and raise them as high as possible. The bent knee targets the soleus.', 'CALVES', ARRAY[]::text[], 'MACHINE', ARRAY[]::text[], FALSE),
(md5('exercise:Bodyweight Calf Raise')::uuid, NULL, 'Bodyweight Calf Raise', 'Stand on the edge of a step, lower your heels below the step and rise onto your toes. Hold something for balance and go slowly.', 'CALVES', ARRAY[]::text[], 'BODYWEIGHT', ARRAY[]::text[], FALSE),
(md5('exercise:Plank')::uuid, NULL, 'Plank', 'Forearms on the floor, body in a straight line from head to heels. Squeeze glutes and abs, breathe steadily. Reps are seconds.', 'CORE', ARRAY['SHOULDERS'], 'BODYWEIGHT', ARRAY['WRIST'], FALSE),
(md5('exercise:Hanging Leg Raise')::uuid, NULL, 'Hanging Leg Raise', 'Hang from a bar and raise your legs, curling your pelvis up toward your ribs. Lower slowly without swinging. Bend the knees to make it easier.', 'CORE', ARRAY['FOREARMS'], 'BODYWEIGHT', ARRAY['SHOULDER'], FALSE),
(md5('exercise:Cable Crunch')::uuid, NULL, 'Cable Crunch', 'Kneel facing a high pulley with a rope at your head. Crunch your ribs toward your pelvis, rounding the spine, then return slowly.', 'CORE', ARRAY[]::text[], 'CABLE', ARRAY[]::text[], FALSE),
(md5('exercise:Ab Wheel Rollout')::uuid, NULL, 'Ab Wheel Rollout', 'From your knees, roll the wheel forward while keeping your abs braced and back flat, then pull it back. Only go as far as you can control.', 'CORE', ARRAY['SHOULDERS', 'BACK'], 'OTHER', ARRAY['LOWER_BACK', 'SHOULDER'], FALSE),
(md5('exercise:Russian Twist')::uuid, NULL, 'Russian Twist', 'Sit leaning back with your feet raised or on the floor. Rotate your torso side to side, touching the floor beside your hips. Hold a weight to progress.', 'CORE', ARRAY[]::text[], 'BODYWEIGHT', ARRAY['LOWER_BACK'], FALSE),
(md5('exercise:Dead Bug')::uuid, NULL, 'Dead Bug', 'On your back with arms up and knees at 90 degrees. Lower the opposite arm and leg while keeping your lower back pressed into the floor, then switch sides.', 'CORE', ARRAY[]::text[], 'BODYWEIGHT', ARRAY[]::text[], FALSE),
(md5('exercise:Bicycle Crunch')::uuid, NULL, 'Bicycle Crunch', 'Hands behind your head, bring opposite elbow and knee together while the other leg extends. Move slowly and keep your lower back down.', 'CORE', ARRAY[]::text[], 'BODYWEIGHT', ARRAY[]::text[], FALSE),
(md5('exercise:Side Plank')::uuid, NULL, 'Side Plank', 'On one forearm with your body in a straight line, hips lifted. Hold without letting the hips sag. Reps are seconds per side.', 'CORE', ARRAY['SHOULDERS'], 'BODYWEIGHT', ARRAY['SHOULDER', 'WRIST'], FALSE),
(md5('exercise:Pallof Press')::uuid, NULL, 'Pallof Press', 'Stand side-on to a cable at chest height. Press the handle straight out and resist the pull trying to rotate you, then bring it back to your chest.', 'CORE', ARRAY['SHOULDERS'], 'CABLE', ARRAY[]::text[], FALSE),
(md5('exercise:Mountain Climber')::uuid, NULL, 'Mountain Climber', 'In a high plank, drive your knees toward your chest alternately at a steady pace. Keep your hips level and shoulders over your hands.', 'CORE', ARRAY['SHOULDERS', 'QUADS'], 'BODYWEIGHT', ARRAY['WRIST'], FALSE),
(md5('exercise:Kettlebell Swing')::uuid, NULL, 'Kettlebell Swing', 'Hike the kettlebell between your legs, then snap your hips forward to swing it to chest height. It is a hip hinge, so the arms just guide. Keep your back flat.', 'GLUTES', ARRAY['HAMSTRINGS', 'BACK', 'CORE'], 'KETTLEBELL', ARRAY['LOWER_BACK'], TRUE),
(md5('exercise:Kettlebell Goblet Squat')::uuid, NULL, 'Kettlebell Goblet Squat', 'Hold the kettlebell by the horns at your chest. Squat deep with an upright torso and drive up through your heels.', 'QUADS', ARRAY['GLUTES', 'CORE'], 'KETTLEBELL', ARRAY['KNEE'], TRUE);
